	public function itemwisesearch() {
		$criteria = new CDbCriteria;

		$criteria->with = array('itemDetail','item','b2bPurchaseBill');
		$criteria->select ='t.*, SUM(t.approved_qty) AS approved_qty, SUM(t.amount) AS amount ';
		$criteria->addCondition('b2bPurchaseBill.status ='. B2bPurchaseBill::STATUS_APPROVED);
		$criteria->group = 'item_detail_id';
		if ((Yii::app ()->session ['start_date'] != '') && (Yii::app ()->session ['end_date'] != '')) {
			$order_ids = array();
			$criteria1 = new CDbCriteria();
			$criteria1->addBetweenCondition ( 't.start_date', Yii::app ()->session ['start_date'], Yii::app ()->session ['end_date'] );
			$criteria1->addCondition('status ='. B2bPurchaseBill::STATUS_APPROVED);
			$B2bPurchaseBill = B2bPurchaseBill::model()->findAll($criteria1);
			
			
			
			// echo"<pre>"; print_r($B2bPurchaseBill); die;
			if($B2bPurchaseBill){
				foreach($B2bPurchaseBill as $order){
					$order_ids[] = $order->id;
				}
			}
			$criteria->addInCondition('t.purchase_bill_id',$order_ids);
			
		}
		
		
		
	
		if(!empty(Yii::app()->session['item_id'])){
			$criteria->addInCondition('item.id', Yii::app()->session['item_id']);
		}else{
			$criteria->compare('item.title', $this->item_id ,true);
		}
		// $criteria->compare('order.customer_id', $this->customer_id);
		$criteria->compare('itemDetail.bar_code', $this->item_detail_id ,true);

		// $criteria->compare('t.tax_amount', $this->tax_amount,true);
		// $criteria->compare('t.purchase_bill_id', $this->id);
		$criteria->compare('t.tax_id', $this->tax_id);
	
		
		$criteria->compare('t.price', $this->price,true);

		$criteria->compare('t.discount_amt', $this->discount_amt,true);

		/* $orderitems = OrderItem::model()->findAll($criteria);
		if($orderitems){
		$total = 0;
			foreach($orderitems as $orderitem){
				
				$total = $total + $orderitem->getItemTotalAmount();
			}
		Yii::app ()->session ['itemwise_total_amt']=number_format($total,2);
		} */
		return new CActiveDataProvider($this, array(
				'criteria' => $criteria,
				'sort'=>array(
						'defaultOrder'=>'t.id DESC',
				),
		));
	}
	
	
	
	
	public function getOrderBillNo()
    {
        $bill_prefix = 'B';
        $billno = $this->purchase_bill_id;
		
		$bill = B2bPurchaseBill::model()->findByPk($this->purchase_bill_id);
		
	
	
        $month = date('m', strtotime($bill->start_date));
        if ($month > 3) {
  $year = date('Y', strtotime($bill->start_date));
			$year= substr($year, -2);
            $yearlast = $year + 1;
			$yearlast= substr($yearlast, -2);
			
			
        } else {
            $year = date('Y', strtotime($bill->start_date));
            $year = $year - 1;
            $yearlast = date('Y', strtotime($bill->start_date));
        }

        $billyear = date('Y', strtotime($bill->start_date));
        $newyear = $billyear + 1;
        $outlet = Outlet::model()->findByPk($this->outlet_id);
        if ($outlet) {
            if ($outlet->bill_prefix == '') {
                $bill_prefix = $outlet->bill_prefix;
            } else {
                $bill_prefix = 'B';
            }
        }
        $_billno = 'B2B' . $year . '-' . $yearlast . '/' . $bill_prefix . '-' . $bill->grn_refrence_no;
        return $_billno;
    }
	
	
