	public function b2bsearch() {
		$order_ids = array();
		if(Yii::app()->session['order_item_item_id'] != ''){
			$this->item_id = Yii::app()->session['order_item_item_id'];
		}
		
		
		if(Yii::app()->session['order_item_customer_id'] != ''){
			$this->customer_id = Yii::app()->session['order_item_customer_id'];
		}
		
		
		if(Yii::app()->session['order_item_create_user_id'] != ''){
			$this->create_user_id = Yii::app()->session['order_item_create_user_id'];
		}
		
	
		Yii::log ( CVarDumper::dumpAsString ( Yii::app()->session['order_item_item_id']  ), CLogger::LEVEL_WARNING, '$orderItems' );
		$criteria1 = new CDbCriteria();
		if ((Yii::app ()->session ['order_item_start_date'] != '') && (Yii::app ()->session ['order_item_end_date'] != '')) {
			$criteria1->addBetweenCondition ( 't.start_date', Yii::app ()->session ['order_item_start_date'], Yii::app ()->session ['order_item_end_date'] );
		}
		if ((Yii::app ()->session ['order_item_min_amt'] != '') && (Yii::app ()->session ['order_item_max_amt'] != '')) {
			$criteria1->addBetweenCondition ( 't.total_Amt', Yii::app ()->session ['order_item_min_amt'], Yii::app ()->session ['order_item_max_amt'] );
		}
		// $criteria1->addCondition('t.status','1');
		$criteria1->addCondition('status ='.B2bPurchaseBill::STATUS_APPROVED);
		$orders = B2bPurchaseBill::model()->findAll($criteria1);
		Yii::log ( CVarDumper::dumpAsString ( Yii::app()->session['order_item_start_date']  ), CLogger::LEVEL_WARNING, '$order_item_start_date' );
		Yii::log ( CVarDumper::dumpAsString ( Yii::app()->session['order_item_end_date']  ), CLogger::LEVEL_WARNING, '$order_item_end_date' );
		if($orders){
			foreach($orders as $order){
				$order_ids[] = $order->id;
			}
		}
		Yii::log ( CVarDumper::dumpAsString ( $order_ids  ), CLogger::LEVEL_WARNING, '$order_ids' );
		$criteria = new CDbCriteria;
		$criteria->addInCondition('t.purchase_bill_id',$order_ids);
		$criteria->with = array('itemDetail','item');
		
		$criteria->compare('item.title', $this->item_id ,true);
		
		// $criteria->compare('B2bPurchaseBill.id', $this->purchase_bill_id);
	
		// $criteria->compare('B2bPurchaseBill.create_user_id', $this->create_user_id);
		// $criteria->compare('b2bpurchase_bill.total_amount', $this->total_amount);
		$criteria->compare('item.mrp', $this->mrp);
		$criteria->compare('itemDetail.bar_code', $this->item_detail_id ,true);
		
		$criteria->compare('t.tax_id', $this->tax_id);
		$criteria->compare('t.tax_amount', $this->tax_amount);
		
		// $criteria->compare('t.qty', $this->qty);
		$criteria->compare('t.price', $this->price);
		// $criteria->compare('t.discount_id', $this->discount_id);
		// $criteria->compare('t.discount_amt', $this->discount_amt);
	
		

		return new CActiveDataProvider($this, array(
			'criteria' => $criteria,
				'pagination' => array (
						'pageSize' => '100'
				),
				'sort'=>array(
						'defaultOrder'=>'t.id DESC',
				),
		));
	}
	
	public function b2bTaxwise() {
	
		$order_ids = array();
		$criteria1 = new CDbCriteria();
		if ((Yii::app ()->session ['order_b2b_start_date'] != '') && (Yii::app ()->session ['order_b2b_end_date'] != '')) {
			$criteria1->addBetweenCondition ( 't.start_date', Yii::app ()->session ['order_b2b_start_date'], Yii::app ()->session ['order_b2b_end_date'] );
		}else{
			$criteria1->addBetweenCondition ( 't.start_date', $this->start_date, $this->end_date );
		}
		if(Yii::app ()->session ['order_mode_payment'] != ''){
		// $criteria1->addCondition ( 't.mode_of_payment ='.Yii::app ()->session ['order_mode_payment']);
		}
		$orders = B2bPurchaseBill::model()->findAll($criteria1);
		if($orders){
			foreach($orders as $order){
				$order_ids[] = $order->id;
			}
		}
	Yii::log ( CVarDumper::dumpAsString ( $order_ids ), CLogger::LEVEL_WARNING, '$order_ids_b2b' );
		$criteria = new CDbCriteria;
		$criteria->addInCondition('purchase_bill_id',$order_ids);
	
		$criteria->with = array('itemDetail','item','b2bPurchaseBill');
		$criteria->group = 't.tax_id';
		//$criteria->group = 't.tax_id,t.order_id';
		$criteria->compare('item.title', $this->item_id ,true);
	
		$criteria->compare('b2bPurchaseBill.bill_no', $this->purchase_bill_id);
		$criteria->compare('b2bPurchaseBill.start_date', $this->start_date);
		$criteria->compare('b2bPurchaseBill.vendor_id', $this->vendor_id);
		$criteria->compare('itemDetail.bar_code', $this->item_detail_id ,true);
	
		$criteria->compare('t.tax_id', $this->tax_id);
		$criteria->compare('t.tax_amount', $this->tax_amount);
		//$criteria->compare ('tax_id', $this->tax_id );
		// $criteria->compare ('t.date(start_date)', $this->start_date );
		$criteria->compare('t.approved_qty', $this->approved_qty);
		$criteria->compare('t.price', $this->price);
		// $criteria->compare('t.discount_id', $this->discount_id);
		// $criteria->compare('t.discount_amt', $this->discount_amt);
		
	
		return new CActiveDataProvider($this, array(
				'criteria' => $criteria,
				'sort'=>array(
						'defaultOrder'=>'t.id DESC',
				),
		));
	}
	
